public int maxSubArray(int[] nums) {
        int max = Integer.MIN_VALUE;
        int preMax = Integer.MIN_VALUE;
        for (int i = 0; i < nums.length; i++) {
            if (i == 0) {
                preMax = nums[i];
            } else {
                preMax = Math.max(preMax + nums[i], nums[i]);
            }
            max = Math.max(max, preMax);
        }
        return max;
    }

